const qs=(s,r=document)=>r.querySelector(s),qsa=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LANG=()=>localStorage.getItem('sv_language')||'en'; const T=(en,hi)=>LANG()==='hi'?hi:en;
const D={home:['Home','मुखपृष्ठ'],students:['Students','विद्यार्थी'],teachers:['Teachers','शिक्षक'],attendance:['Attendance','उपस्थिति'],requests:['Requests','अनुरोध'],timetable:['Time Table','समय-सारणी'],welfare:['Welfare','कल्याण'],inventory:['Inventory','भंडार'],exams:['Exams','परीक्षाएँ'],results:['Results','परिणाम'],certificates:['Certificates','प्रमाण-पत्र'],notices:['Notices','सूचनाएँ'],notifications:['Notifications','सूचनाएँ'],svcet:['SVCET','एसवीसीईटी'],reports:['Reports','प्रतिवेदन'],users:['User Management','उपयोगकर्ता प्रबंधन'],settings:['Settings','सेटिंग्स'],faceAttendance:['Face Attendance','चेहरा आधारित उपस्थिति'],faceRegistration:['Face Registration','चेहरा पंजीकरण'],logout:['Logout','लॉग आउट'],theme:['Theme','थीम'],search:['Search anything in the app…','ऐप में कुछ भी खोजें…'],back:['Back','वापस'],studentAttendance:['Student Attendance','विद्यार्थी उपस्थिति'],teacherAttendance:['Teacher Attendance','शिक्षक उपस्थिति'],attendanceSummary:['Attendance Summary','उपस्थिति सारांश'],holidays:['Holidays','अवकाश'],newRequest:['New Request','नया अनुरोध'],myRequests:['My Requests','मेरे अनुरोध'],more:['More','अधिक']};
const L=k=>T(...(D[k]||[k,k]));
const META={students:['👨‍🎓','Students','विद्यार्थी','Admission, profiles, documents and student records','प्रवेश, प्रोफ़ाइल, दस्तावेज़ एवं विद्यार्थी अभिलेख'],teachers:['👨‍🏫','Teachers','शिक्षक','Teacher records, classes and subject assignments','शिक्षक अभिलेख, कक्षाएँ एवं विषय दायित्व'],attendance:['✅','Attendance','उपस्थिति','Manual records, face registration and automatic attendance','मैनुअल अभिलेख, चेहरा पंजीकरण एवं स्वचालित उपस्थिति'],requests:['📝','Requests','अनुरोध','Teacher leave and other applications','शिक्षक अवकाश एवं अन्य आवेदन'],timetable:['🗓️','Time Table','समय-सारणी','Class and teacher schedules','कक्षा एवं शिक्षक समय-सारणी'],welfare:['🎁','Welfare','कल्याण','Student welfare distribution records','विद्यार्थी कल्याण वितरण अभिलेख'],inventory:['📦','Inventory','भंडार','Stock, issue and return management','भंडार, निर्गमन एवं वापसी प्रबंधन'],exams:['📝','Exams','परीक्षाएँ','Exam setup, schedule and marks entry','परीक्षा निर्धारण, समय-सारणी एवं अंक प्रविष्टि'],results:['🏆','Results','परिणाम','Student results and merit information','विद्यार्थी परिणाम एवं मेधा विवरण'],certificates:['📜','Certificates','प्रमाण-पत्र','Create and manage certificates','प्रमाण-पत्र बनाएँ एवं प्रबंधित करें'],notifications:['🔔','Notices','सूचनाएँ','Notices and important updates','सूचनाएँ एवं महत्वपूर्ण अद्यतन'],svcet:['🎓','SVCET','एसवीसीईटी','Entrance test registrations and results','प्रवेश परीक्षा पंजीकरण एवं परिणाम'],reports:['📊','Reports','प्रतिवेदन','Centre reports and records','केंद्र प्रतिवेदन एवं अभिलेख'],users:['👤','User Management','उपयोगकर्ता प्रबंधन','Admin, Teacher and Student accounts','प्रशासक, शिक्षक एवं विद्यार्थी खाते'],settings:['⚙️','Settings','सेटिंग्स','Centre and application preferences','केंद्र एवं ऐप प्राथमिकताएँ']};
function user(){try{return typeof currentUser==='function'?currentUser():null}catch(e){return null}}
function role(){let r=user()?.role||'Admin';if(['Super Administrator','Administrator','Principal','Office Admin','Librarian','Store Keeper','Store Manager'].includes(r))r='Admin';if(r==='Guardian')r='Student';return ['Admin','Teacher','Student'].includes(r)?r:'Admin'}
const CAPS={Admin:['dashboard','students','teachers','attendance','requests','timetable','welfare','inventory','exams','results','certificates','notifications','svcet','reports','users','settings'],Teacher:['dashboard','students','attendance','requests','timetable','exams','results','notifications','settings'],Student:['dashboard','attendance','timetable','exams','results','certificates','notifications','settings']};
function allowed(m){return m==='dashboard'||CAPS[role()]?.includes(m)}
function db(key,fallback){try{return Database.getAll((CONFIG.STORAGE&&CONFIG.STORAGE[key])||fallback)||[]}catch(e){try{return JSON.parse(localStorage.getItem(fallback)||'[]')}catch(_){return []}}}
function save(key,fallback,rows){try{Database.saveAll((CONFIG.STORAGE&&CONFIG.STORAGE[key])||fallback,rows)}catch(e){localStorage.setItem(fallback,JSON.stringify(rows))}}
function hideLegacy(){['#appHeader','#appSidebar','#appFooter'].forEach(x=>{let e=qs(x);if(e)e.style.display='none'})}
function setBody(m){document.body.classList.remove('sv-home-mode','sv-inner-mode','sv-login-mode');document.body.classList.add(m)}
function removeShell(){qs('.sv-home-header')?.remove();qs('.sv-bottom-nav')?.remove();qs('#svSearchResults')?.remove()}
function homeHeader(){qs('.sv-home-header')?.remove();let h=document.createElement('header');h.className='sv-home-header';h.innerHTML=`<div class="sv-brand"><img src="assets/images/logo.png" alt="SV"><div class="sv-brand-title"><b>Sewangan Vidyapeeth</b><small>${T('A Free Coaching Initiative • Sewangan Charitable Trust','निःशुल्क कोचिंग पहल • सेवांगन चैरिटेबल ट्रस्ट')}</small></div></div><div class="sv-head-actions"><button class="sv-icon-btn" onclick="SV10.open('notifications')" aria-label="${L('notifications')}">🔔</button><button class="sv-icon-btn" onclick="SV10.toggleLanguage()">${LANG()==='hi'?'EN':'हिं'}</button></div>`;document.body.insertBefore(h,document.body.firstChild)}
function bottom(active='home'){qs('.sv-bottom-nav')?.remove();let student=role()==='Student';let items=student?[['dashboard','⌂','home'],['attendance','✓','attendance'],['notifications','🔔','notices'],['more','☰','more']]:[['dashboard','⌂','home'],['students','♟','students'],['attendance','✓','attendance'],['notifications','🔔','notices'],['more','☰','more']];let n=document.createElement('nav');n.className='sv-bottom-nav';n.innerHTML=items.map(([m,i,k])=>`<button class="${active===k?'active':''}" onclick="${m==='more'?'SV10.more()':`SV10.open('${m}')`}"><span class="ico">${i}</span><span>${L(k)}</span></button>`).join('');document.body.appendChild(n)}
const HA=[['students','👨‍🎓'],['teachers','👨‍🏫'],['attendance','✅'],['requests','📝'],['timetable','🗓️'],['welfare','🎁'],['inventory','📦'],['exams','📝'],['results','🏆'],['certificates','📜']];
const HT=[['students','👨‍🎓'],['attendance','✅'],['requests','📝'],['timetable','🗓️'],['exams','📝'],['results','🏆'],['notifications','🔔']];
const HS=[['attendance','✅'],['notifications','🔔'],['timetable','🗓️'],['exams','📝'],['results','🏆'],['certificates','📜'],['settings','⚙️']];
function homeItems(){return role()==='Admin'?HA:role()==='Teacher'?HT:HS}
function renderHome(){stopCamera();hideLegacy();removeShell();homeHeader();bottom('home');setBody('sv-home-mode');let main=qs('#mainContent');if(!main)return;let students=db('STUDENTS','svms_students'),teachers=db('TEACHERS','svms_teachers');let face=role()==='Student'?'':`<button class="sv-face-home" onclick="SV10.faceAttendance()"><span class="ico">📷</span><span><b>${L('faceAttendance')}</b><small>${T('Automatic Student + Teacher recognition and attendance','विद्यार्थी + शिक्षक की स्वतः पहचान एवं उपस्थिति')}</small></span></button>`;let rows=homeItems().map(([m,i])=>`<button class="sv-q" onclick="SV10.open('${m}')"><span class="i">${i}</span><b>${L(m==='notifications'?'notices':m)}</b></button>`).join('');main.innerHTML=`<div class="sv-home ${role()==='Student'?'no-face':''}"><div class="sv-search"><span class="mag">⌕</span><input id="svSearch" placeholder="${L('search')}" autocomplete="off"><button class="clear" onclick="SV10.clearSearch()">×</button></div><div class="sv-stats"><button class="sv-stat students" onclick="SV10.open('students')"><span>${L('students')}</span><strong>${students.length}</strong></button><button class="sv-stat teachers" onclick="SV10.open('teachers')"><span>${L('teachers')}</span><strong>${teachers.length}</strong></button></div>${face}<div class="sv-quick">${rows}</div></div>`;let inp=qs('#svSearch');if(inp)inp.addEventListener('input',e=>search(e.target.value))}
function moduleHeader(m){let a=META[m]||['📱',m,m,'',''];return `<div class="sv-module-top"><div class="sv-module-card"><span class="icon">${a[0]}</span><span class="sv-module-copy"><b>${T(a[1],a[2])}</b><small>${T(a[3],a[4])}</small></span></div><button class="sv-back3d" onclick="SV10.back()">← ${L('back')}</button></div>`}
function linkedChildren(){let u=user()||{},all=db('STUDENTS','svms_students'),ids=[];if(u.studentId)ids.push(u.studentId);if(Array.isArray(u.studentIds))ids.push(...u.studentIds);if(typeof u.studentIds==='string')ids.push(...u.studentIds.split(',').map(x=>x.trim()).filter(Boolean));let gid=u.guardianId||u.userId||'',mobile=u.mobile||u.phone||'';return all.filter(s=>ids.includes(s.studentId)||(gid&&s.guardianId===gid)||(mobile&&(s.guardianMobile===mobile||s.parentMobile===mobile)))}
function guardianFilter(rows,children){let ids=new Set(children.map(x=>x.studentId)),classes=new Set(children.map(x=>x.studentClass||x.class).filter(Boolean));return rows.filter(r=>ids.has(r.studentId)||ids.has(r.childId)||classes.has(r.studentClass)||classes.has(r.class)||(!r.studentId&&!r.childId&&!r.studentClass&&!r.class))}
function guardianPage(m){let main=qs('#mainContent'),kids=linkedChildren();if(!kids.length){main.innerHTML=`<div class="card"><h3>${T('Child profile not linked','बच्चे की प्रोफ़ाइल लिंक नहीं है')}</h3><p>${T('Please ask the centre Admin to link this account with the student profile.','कृपया केंद्र प्रशासक से इस खाते को विद्यार्थी प्रोफ़ाइल से लिंक करवाएँ।')}</p></div>`;return}let rows=[],title=L(m==='notifications'?'notices':m);if(m==='attendance')rows=guardianFilter(db('ATTENDANCE','svms_attendance'),kids);else if(m==='timetable')rows=guardianFilter(db('TIMETABLE','svms_timetable'),kids);else if(m==='exams')rows=guardianFilter(db('EXAMS','svms_exams'),kids);else if(m==='results')rows=guardianFilter(db('RESULTS','svms_results'),kids);else if(m==='certificates')rows=guardianFilter(db('CERTIFICATES','svms_certificates'),kids);else if(m==='notifications')rows=guardianFilter(db('NOTIFICATIONS','svms_notifications'),kids);let childCards=kids.map(k=>`<div style="padding:9px;border-radius:12px;background:#fff3e4;margin-bottom:7px"><b>${esc(k.studentName||k.name||k.studentId)}</b><div style="font-size:10px;margin-top:2px">${esc(k.studentId||'')} ${k.studentClass||k.class?'• '+esc(k.studentClass||k.class):''}</div></div>`).join('');let list=rows.length?rows.slice().reverse().slice(0,80).map(r=>{let image=r.imageUrl||r.attachmentData||'';let primary=r.title||r.examName||r.certificateType||r.subject||r.studentName||r.date||title;let secondary=[r.date,r.assignedDate,r.dueDate,r.status,r.marks!=null?`${r.marks}/${r.maximumMarks||r.maxMarks||''}`:'',r.message,r.description].filter(Boolean).join(' • ');return `<div style="border:1px solid var(--border);border-radius:12px;padding:9px;margin-bottom:7px"><b>${esc(primary)}</b><div style="font-size:10.5px;margin-top:3px;line-height:1.35">${esc(secondary)}</div>${image?`<img class="sv-image-preview" src="${esc(image)}" alt="">`:''}</div>`}).join(''):`<div style="padding:15px;text-align:center;color:var(--muted)">${T('No records available.','कोई अभिलेख उपलब्ध नहीं है।')}</div>`;main.innerHTML=`<div class="page"><div class="card">${childCards}</div><div class="card"><h3>${title}</h3>${list}</div></div>`}
function invoke(m){if(role()==='Student'&&['attendance','timetable','exams','results','certificates','notifications'].includes(m))return guardianPage(m);switch(m){case'students':return Students.render();case'teachers':return Teachers.render();case'attendance':return renderAttendance();case'requests':return renderRequests();case'timetable':return Timetable.render();case'welfare':return Welfare.render();case'inventory':return Inventory.render();case'exams':return Exams.render();case'results':return Results.render();case'certificates':return Certificates.render();case'notifications':return Notifications.render();case'svcet':return SVCET.render();case'reports':return Reports.render();case'users':return renderUsers12();case'settings':return Settings.render();default:return renderHome()}}
function decorate(m){hideLegacy();qs('.sv-home-header')?.remove();setBody('sv-inner-mode');bottom(m==='students'?'students':m==='attendance'?'attendance':'');let main=qs('#mainContent');if(!main)return;if(!qs('.sv-module-top',main)){let old=main.innerHTML;main.innerHTML=moduleHeader(m)+`<div class="sv-module-body">${old}</div>`}translate(main);bindImages(main);normalizeRoles(main);setTimeout(()=>beautifyRegisters(m),20)}
function open(m){if(m==='dashboard')return renderHome();if(!allowed(m)){alert(T('You do not have permission to open this section.','आपको यह अनुभाग खोलने की अनुमति नहीं है।'));return}stopCamera();removeShell();let main=qs('#mainContent');if(main)main.innerHTML='';try{invoke(m)}catch(e){console.error(e);if(main)main.innerHTML=`<div class="card"><h3>${T('Unable to open this module','यह मॉड्यूल नहीं खुल सका')}</h3><p>${esc(e.message||'')}</p></div>`}setTimeout(()=>decorate(m),10)}
function back(){renderHome()}
function renderAttendance(){let main=qs('#mainContent'),student=role()==='Student';main.innerHTML=`<div class="page"><div class="card"><div class="sv-att-grid">${student?'':`<button class="sv-att-card" onclick="SV10.faceAttendance()"><span>📷</span><b>${L('faceAttendance')}</b></button>`}${role()==='Admin'?`<button class="sv-att-card" onclick="SV10.faceRegistrationChooser()"><span>🧑‍💻</span><b>${L('faceRegistration')}</b></button>`:''}<button class="sv-att-card" onclick="studentAttendancePage()"><span>👨‍🎓</span><b>${L('studentAttendance')}</b></button>${student?'':`<button class="sv-att-card" onclick="teacherAttendancePage()"><span>👨‍🏫</span><b>${L('teacherAttendance')}</b></button>`}<button class="sv-att-card" onclick="attendanceSummaryPage()"><span>📊</span><b>${L('attendanceSummary')}</b></button>${student?'':`<button class="sv-att-card" onclick="Holiday.render()"><span>📅</span><b>${L('holidays')}</b></button>`}</div></div></div>`}
function renderRequests(){let main=qs('#mainContent'),apps=db('APPLICATIONS','sv_teacher_applications');if(role()==='Student'){main.innerHTML=`<div class="card">${T('Requests are available only to teachers and admins.','अनुरोध केवल शिक्षक और प्रशासक के लिए उपलब्ध हैं।')}</div>`;return}let mine=role()==='Teacher'?apps.filter(a=>!user()?.teacherId||a.teacherId===user().teacherId):apps;main.innerHTML=`<div class="page"><div class="card"><button class="btn" onclick="SV10.requestForm()">＋ ${L('newRequest')}</button></div><div class="card">${mine.length?mine.map(a=>`<div style="border:1px solid var(--border);border-radius:12px;padding:9px;margin-bottom:7px"><b>${esc(a.title||a.type||'Request')}</b><div style="font-size:11px;margin-top:3px">${esc(a.date||'')} • ${esc(a.status||'Pending')}</div><div style="font-size:11px;margin-top:3px">${esc(a.description||'')}</div></div>`).join(''):`<p>${T('No requests found.','कोई अनुरोध नहीं मिला।')}</p>`}</div></div>`}
function requestForm(){openModal(`<div class="card"><label>${T('Type','प्रकार')}</label><select id="rqType"><option>Leave</option><option>Late Arrival</option><option>Early Departure</option><option>Personal Issue</option><option>Class Issue</option><option>Student Issue</option><option>Other</option></select><label>${T('Date','तिथि')}</label><input id="rqDate" type="date"><label>${T('Title','शीर्षक')}</label><input id="rqTitle"><label>${T('Description','विवरण')}</label><textarea id="rqDesc"></textarea><label>${T('Attachment','संलग्नक')}</label><input id="rqFile" type="file" accept="image/*,.pdf"><button class="btn" onclick="SV10.saveRequest()">${T('Submit','जमा करें')}</button></div>`,L('newRequest'))}
function saveRequest(){let rows=db('APPLICATIONS','sv_teacher_applications');rows.push({applicationId:'REQ-'+Date.now(),teacherId:user()?.teacherId||user()?.userId||'',teacherName:user()?.name||'',type:qs('#rqType')?.value||'',date:qs('#rqDate')?.value||'',title:qs('#rqTitle')?.value||'',description:qs('#rqDesc')?.value||'',status:'Pending',createdAt:new Date().toISOString()});save('APPLICATIONS','sv_teacher_applications',rows);closeModal();open('requests')}
function openModal(html,title){closeModal();let d=document.createElement('div');d.className='sv-modal';d.id='svModal';d.innerHTML=`<div class="sv-modal-panel"><div class="sv-modal-head"><div class="sv-modal-title">${esc(title||T('Form','प्रपत्र'))}</div><button class="sv-modal-close" onclick="SV10.closeModal()">← ${L('back')}</button></div><div class="sv-modal-body">${html}</div></div>`;document.body.appendChild(d);bindImages(d);normalizeRoles(d);translate(d)}
function closeModal(){stopCamera();if(movedForm&&movedForm.ph?.parentNode){movedForm.ph.parentNode.insertBefore(movedForm.node,movedForm.ph);movedForm.ph.remove();movedForm=null}qs('#svModal')?.remove()}
/* Convert legacy Add/Edit/Admission/etc. screens to true full-screen form popups. */
document.addEventListener('click',e=>{let b=e.target.closest('button,a');if(!b||qs('#svModal'))return;let oc=(b.getAttribute('onclick')||'').toLowerCase(),tx=(b.textContent||'').toLowerCase();if(/sv10\.|router\.open|dashboard\.render/.test(oc))return;if(!/(add|new|edit|admission|promot|transfer|issue|return|create|generate|assign|register|upload|application|marks|profile photo|document)/.test(oc+' '+tx))return;let main=qs('#mainContent');if(!main)return;let before=main.innerHTML,title=(b.textContent||T('Form','प्रपत्र')).trim();[50,160,350].forEach(delay=>setTimeout(()=>captureLegacyForm(main,before,title),delay))},true);

function captureLegacyForm(main,before,title){
  if(qs('#svModal')||!main)return;
  let candidates=qsa('form,[id*="form" i],[class*="form" i]',main).filter(x=>{
    let controls=qsa('input,select,textarea,button',x).length;
    let st=getComputedStyle(x);return controls>=2&&st.display!=='none'&&st.visibility!=='hidden';
  });
  let node=candidates.find(x=>x.offsetParent!==null);
  if(node){let holder=node.closest('.card')||node;openModalNode(holder,title);return}
  let after=main.innerHTML;if(after&&after!==before){main.innerHTML=before;openModal(after,title)}
}
let movedForm=null;
function openModalNode(node,title){
  closeModal(); if(!node)return;
  let ph=document.createComment('sv-form-placeholder');node.parentNode.insertBefore(ph,node);
  let d=document.createElement('div');d.className='sv-modal';d.id='svModal';
  d.innerHTML=`<div class="sv-modal-panel"><div class="sv-modal-head"><div class="sv-modal-title">${esc(title||T('Form','प्रपत्र'))}</div><button class="sv-modal-close" onclick="SV10.closeModal()">← ${L('back')}</button></div><div class="sv-modal-body"></div></div>`;
  document.body.appendChild(d);qs('.sv-modal-body',d).appendChild(node);node.style.display='block';movedForm={node,ph};bindImages(d);normalizeRoles(d);translate(d);setTimeout(()=>qs('input:not([type=hidden]),select,textarea',d)?.focus(),80)
}
function bindImages(root=document){qsa('input[type=file]',root).forEach(inp=>{if(inp.dataset.sv10)return;inp.dataset.sv10='1';inp.addEventListener('change',()=>{let f=inp.files?.[0];if(!f||!f.type.startsWith('image/'))return;let r=new FileReader();r.onload=()=>{inp.dataset.imageData=r.result;let p=inp.nextElementSibling?.classList?.contains('sv-image-preview')?inp.nextElementSibling:document.createElement('img');p.className='sv-image-preview';p.src=r.result;if(!p.parentNode)inp.insertAdjacentElement('afterend',p)};r.readAsDataURL(f)})})}
function more(){qs('#svSheet')?.remove();let r=role(),items=r==='Admin'?[['notifications','🔔'],['svcet','🎓'],['reports','📊'],['users','👤'],['settings','⚙️'],['faceRegistration','🧑‍💻']]:r==='Teacher'?[['notifications','🔔'],['settings','⚙️']]:[['settings','⚙️']];let html=items.map(([m,i])=>m==='faceRegistration'?`<button class="sv-more-item" onclick="SV10.closeSheet();SV10.faceRegistrationChooser()"><span>${i}</span><b>${L('faceRegistration')}</b></button>`:`<button class="sv-more-item" onclick="SV10.closeSheet();SV10.open('${m}')"><span>${i}</span><b>${L(m==='notifications'?'notices':m)}</b></button>`).join('');html+=`<button class="sv-more-item" onclick="SV10.cycleTheme()"><span>◐</span><b>${L('theme')}</b></button><button class="sv-more-item" onclick="SV10.logout()"><span>🚪</span><b>${L('logout')}</b></button>`;let d=document.createElement('div');d.className='sv-sheet';d.id='svSheet';d.onclick=e=>{if(e.target===d)d.remove()};d.innerHTML=`<div class="sv-sheet-panel"><div class="sv-sheet-handle"></div><div class="sv-sheet-title"><b>${L('more')}</b><button class="sv-sheet-close" onclick="SV10.closeSheet()">×</button></div><div class="sv-more-grid">${html}</div></div>`;document.body.appendChild(d)}
