function search(q){qs('#svSearchResults')?.remove();q=String(q||'').trim().toLowerCase();if(!q)return;let rec=[];Object.entries(META).forEach(([m,a])=>{if(allowed(m)&&(m+' '+a.join(' ')).toLowerCase().includes(q))rec.push({m,title:T(a[1],a[2]),text:T(a[3],a[4])})});if(role()!=='Student')try{for(let i=0;i<localStorage.length;i++){let k=localStorage.key(i),v=localStorage.getItem(k)||'';if(!v.toLowerCase().includes(q))continue;let kl=k.toLowerCase(),m=kl.includes('student')?'students':kl.includes('teacher')?'teachers':kl.includes('attendance')?'attendance':kl.includes('exam')?'exams':kl.includes('result')?'results':kl.includes('certificate')?'certificates':kl.includes('notice')?'notifications':null;if(m&&allowed(m))rec.push({m,title:L(m==='notifications'?'notices':m),text:v.replace(/[{}\[\]"]/g,' ').slice(0,130)})}}catch(e){}let seen=new Set(),u=rec.filter(x=>{let k=x.m+x.title+x.text;if(seen.has(k))return false;seen.add(k);return true});let d=document.createElement('div');d.id='svSearchResults';d.className='sv-search-results';d.innerHTML=u.length?u.slice(0,24).map(x=>`<button class="sv-search-hit" onclick="SV10.clearSearch();SV10.open('${x.m}')"><b>${esc(x.title)}</b><small>${esc(x.text)}</small></button>`).join(''):`<div class="sv-search-empty">${T('No matching content found.','मिलती-जुलती सामग्री नहीं मिली।')}</div>`;document.body.appendChild(d)}
