const registerCache={};
function beautifyRegisters(module){
  let body=qs('.sv-module-body');if(!body)return;
  qsa('table',body).forEach((table,ti)=>{
    if(table.dataset.svRegister)return;
    let headers=qsa('thead th',table).map(x=>x.textContent.trim());if(!headers.length){let first=qs('tr',table);headers=qsa('th,td',first||table).map(x=>x.textContent.trim())}
    let ni=headers.findIndex(h=>/student\s*name|teacher\s*name|candidate\s*name|beneficiary\s*name|^name$|विद्यार्थी.*नाम|शिक्षक.*नाम|अभ्यर्थी.*नाम|^नाम$/i.test(h));
    if(ni<0)return;
    let rows=qsa('tbody tr',table);if(!rows.length)rows=qsa('tr',table).slice(1);if(!rows.length)return;
    let records=rows.map(tr=>qsa('td',tr).map(td=>td.innerText.trim()));
    let id=`${module}-${Date.now()}-${ti}`;registerCache[id]={headers,records,title:(META[module]?T(META[module][1],META[module][2]):module)};
    let wrap=document.createElement('div');wrap.className='sv-register';
    wrap.innerHTML=`<div class="sv-register-toolbar"><span><b>${registerCache[id].title}</b><small>${records.length} ${T('records','अभिलेख')}</small></span><button onclick="SV10.exportRegister('${id}')">⬇ XLSX</button></div><div class="sv-name-list">${records.map((r,i)=>`<button onclick="SV10.showRegisterRecord('${id}',${i})"><span class="sv-name-avatar">${esc((r[ni]||'?').trim().charAt(0).toUpperCase()||'?')}</span><b>${esc(r[ni]||T('Unnamed','बिना नाम'))}</b><span>›</span></button>`).join('')}</div>`;
    table.dataset.svRegister='1';table.style.display='none';table.insertAdjacentElement('beforebegin',wrap)
  })
}
function showRegisterRecord(id,i){let c=registerCache[id],r=c?.records?.[i];if(!c||!r)return;let rows=c.headers.map((h,j)=>r[j]?`<div class="sv-detail-row"><span>${esc(h||T('Field','विवरण'))}</span><b>${esc(r[j])}</b></div>`:'').join('');openModal(`<div class="card sv-detail-card">${rows}</div>`,r[c.headers.findIndex(h=>/name|नाम/i.test(h))]||c.title)}
function exportRegister(id){let c=registerCache[id];if(!c)return;if(!window.XLSX){alert(T('XLSX exporter is not loaded. Connect to internet once and reopen the app.','XLSX निर्यातक लोड नहीं हुआ है। एक बार इंटरनेट से जुड़कर ऐप दोबारा खोलें।'));return}let title=`Sewangan Vidyapeeth - ${c.title}`;let aoa=[[title],[],c.headers,...c.records];let ws=XLSX.utils.aoa_to_sheet(aoa);ws['!merges']=[{s:{r:0,c:0},e:{r:0,c:Math.max(0,c.headers.length-1)}}];ws['!cols']=c.headers.map((h,j)=>({wch:Math.min(34,Math.max(12,h.length+3,...c.records.map(r=>String(r[j]||'').length+2)))}));let wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Register');XLSX.writeFile(wb,`${c.title.replace(/[^a-z0-9\u0900-\u097F]+/gi,'_')}_Register.xlsx`)}
/* FACE ENGINE: offline detector + tiny landmarks only; no incomplete recognition shard dependency. */
let stream=null,scanning=false,cooldown=new Map(),modelsReady=false;
async function models(){if(modelsReady)return;const p='assets/face-api/models';await faceapi.nets.tinyFaceDetector.loadFromUri(p);await faceapi.nets.faceLandmark68TinyNet.loadFromUri(p);modelsReady=true}
async function camera(video){stopCamera();if(!navigator.mediaDevices?.getUserMedia)throw new Error(T('Camera is not supported on this device.','इस उपकरण पर कैमरा समर्थित नहीं है।'));stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:720},height:{ideal:960}},audio:false});video.srcObject=stream;await new Promise((res,rej)=>{let done=false;video.onloadedmetadata=()=>{if(!done){done=true;video.play().then(res).catch(rej)}};setTimeout(()=>{if(!done){done=true;video.play().then(res).catch(rej)}},1200)});return stream}
function stopCamera(){scanning=false;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}try{CameraManager?.stop?.()}catch(e){}}
function signature(det){let b=det.detection.box,w=Math.max(1,b.width),h=Math.max(1,b.height);return det.landmarks.positions.flatMap(p=>[(p.x-b.x)/w,(p.y-b.y)/h])}
function sigDistance(a,b){if(!a||!b||a.length!==b.length)return 99;let s=0;for(let i=0;i<a.length;i++){let d=a[i]-b[i];s+=d*d}return Math.sqrt(s/a.length)}
function allPeople(type){let rows=type==='Student'?db('STUDENTS','svms_students'):db('TEACHERS','svms_teachers');if(rows.length)return rows;let found=[];if(role()!=='Student')try{for(let i=0;i<localStorage.length;i++){let k=localStorage.key(i)||'';if(!k.toLowerCase().includes(type.toLowerCase()))continue;let x=JSON.parse(localStorage.getItem(k)||'[]');if(Array.isArray(x))found.push(...x)}}catch(e){}return found}
function faceRegistrationChooser(type='Student'){if(role()!=='Admin'){alert(T('Only Admin can register faces.','केवल प्रशासक चेहरा पंजीकृत कर सकता है।'));return}openModal(`<div class="card sv-reg-card"><b>${T('Choose person type','व्यक्ति का प्रकार चुनें')}</b><div class="sv-person-type"><button id="svTypeStudent" onclick="SV10.setFaceType('Student')">👨‍🎓 ${L('students')}</button><button id="svTypeTeacher" onclick="SV10.setFaceType('Teacher')">👨‍🏫 ${L('teachers')}</button></div><div class="sv-reg-search"><input id="svRegSearch" placeholder="${T('Search name or ID','नाम या आईडी खोजें')}" oninput="SV10.filterFacePeople(this.value)"></div><div id="svFacePeople" class="sv-face-people"></div><div id="svFaceEmpty" class="sv-face-empty" style="display:none"></div><button class="btn sv-reg-start" id="svStartReg" disabled onclick="SV10.startRegistration()">📷 ${L('faceRegistration')}</button></div>`,L('faceRegistration'));setFaceType(type)}
let facePeopleRows=[];
function setFaceType(type){let rows=allPeople(type);facePeopleRows=rows.map(x=>({raw:x,type,id:type==='Student'?(x.studentId||x.registrationNo||x.admissionNo||x.id):(x.teacherId||x.employeeId||x.id),name:type==='Student'?(x.studentName||x.name||x.fullName):(x.teacherName||x.name||x.fullName)})).filter(x=>x.id||x.name);let box=qs('#svFacePeople'),empty=qs('#svFaceEmpty'),btn=qs('#svStartReg');qsa('.sv-person-type button').forEach(b=>b.classList.remove('active'));qs(type==='Student'?'#svTypeStudent':'#svTypeTeacher')?.classList.add('active');if(box)box.dataset.type=type;if(!facePeopleRows.length){if(box)box.innerHTML='';if(empty){empty.style.display='block';empty.textContent=type==='Student'?T('No students found. Add students first.','कोई विद्यार्थी नहीं मिला। पहले विद्यार्थी जोड़ें।'):T('No teachers found. Add teachers first.','कोई शिक्षक नहीं मिला। पहले शिक्षक जोड़ें।')}if(btn)btn.disabled=true;return}if(empty)empty.style.display='none';renderFacePeople(facePeopleRows)}
function renderFacePeople(rows){let box=qs('#svFacePeople');if(!box)return;box.innerHTML=rows.map((x,i)=>`<button class="sv-face-person" data-id="${esc(x.id||'')}" onclick="SV10.selectFacePerson(this,'${esc(x.id||'')}')"><span class="avatar">${x.type==='Student'?'👨‍🎓':'👨‍🏫'}</span><span><b>${esc(x.name||x.id)}</b><small>${esc(x.id||'')}</small></span><span class="tick">✓</span></button>`).join('')}
function filterFacePeople(q){q=String(q||'').toLowerCase();renderFacePeople(facePeopleRows.filter(x=>(x.name+' '+x.id).toLowerCase().includes(q)))}
function selectFacePerson(el,id){qsa('.sv-face-person').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');let box=qs('#svFacePeople');box.dataset.selected=id;let btn=qs('#svStartReg');if(btn)btn.disabled=false}
async function startRegistration(){let box=qs('#svFacePeople'),type=box?.dataset.type||'Student',id=box?.dataset.selected||'';if(window.SV357?.faceRegistration){closeModal();return SV357.faceRegistration(type,id)}return}
async function faceAttendance(){if(role()==='Student')return;stopCamera();removeShell();hideLegacy();setBody('sv-inner-mode');bottom('attendance');let main=qs('#mainContent');main.innerHTML=moduleHeader('attendance')+`<div class="sv-module-body"><div class="card"><div class="sv-camera-status" id="svFaceStatus">${T('Loading face engine…','चेहरा पहचान प्रणाली लोड हो रही है…')}</div><div class="sv-recognition" id="svFaceInfo">${T('Student and Teacher are identified automatically.','विद्यार्थी और शिक्षक की पहचान स्वतः होगी।')}</div><div class="sv-camera-box"><video id="svFaceVideo" autoplay playsinline muted></video><canvas id="svFaceCanvas"></canvas></div></div></div>`;try{await models();let v=qs('#svFaceVideo');qs('#svFaceStatus').textContent=T('Opening camera…','कैमरा खुल रहा है…');await camera(v);scanning=true;while(scanning&&v.srcObject){let det=await faceapi.detectSingleFace(v,new faceapi.TinyFaceDetectorOptions({inputSize:224,scoreThreshold:.55})).withFaceLandmarks(true);if(det)recognize(det);else qs('#svFaceStatus').textContent=T('Looking for a registered face…','पंजीकृत चेहरा खोजा जा रहा है…');await new Promise(r=>setTimeout(r,360))}}catch(e){console.error(e);let s=qs('#svFaceStatus');if(s)s.textContent=e.name==='NotAllowedError'?T('Camera permission denied. Please allow camera access.','कैमरा अनुमति अस्वीकार हुई। कृपया कैमरा अनुमति दें।'):e.message||T('Camera unavailable','कैमरा उपलब्ध नहीं है')}}
async function recognize(det){let pool=[...allPeople('Student').map(p=>({type:'Student',p})),...allPeople('Teacher').map(p=>({type:'Teacher',p}))].filter(x=>Array.isArray(x.p.faceLandmarkSignature));if(!pool.length){qs('#svFaceStatus').textContent=T('No registered faces found. Register faces first.','कोई पंजीकृत चेहरा नहीं मिला। पहले चेहरा पंजीकृत करें।');return}let sig=signature(det),best=null,dist=99;pool.forEach(x=>{let d=sigDistance(sig,x.p.faceLandmarkSignature);if(d<dist){dist=d;best=x}});if(!best||dist>.075){qs('#svFaceStatus').textContent=T('Face not recognised','चेहरा पहचाना नहीं गया');return}let id=best.type==='Student'?(best.p.studentId||best.p.id):(best.p.teacherId||best.p.id),name=best.type==='Student'?(best.p.studentName||best.p.name):(best.p.teacherName||best.p.name),k=best.type+'|'+id,now=Date.now();if(cooldown.has(k)&&now-cooldown.get(k)<15000){qs('#svFaceStatus').textContent=name;return}cooldown.set(k,now);qs('#svFaceStatus').textContent=T('Saving attendance…','उपस्थिति सहेजी जा रही है…');try{let token=localStorage.getItem('sv_api_token')||sessionStorage.getItem('sv_api_token')||'',r=await fetch('https://script.google.com/macros/s/AKfycbytewRtpvCG2IXcbE_TryG58AOtp_MImIyikI_bMeIVlhPCVkF2PIrprr-RCG9wfjWJ0A/exec',{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'markFaceAttendance',token,personType:best.type,personId:id,confidence:Math.max(0,Math.round((1-dist/.075)*100))})}),j=await r.json();if(!j.ok)throw new Error(j.message||'Attendance save failed');let ev=j.eventType||'arrival',rec=j.data||{},rawTime=ev==='departure'?rec.departureTime:rec.arrivalTime,tm=window.SV357?.fmtTime12?.(rawTime)||rawTime||new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',hour12:true}),label=ev==='departure'?T('Departure marked','प्रस्थान दर्ज'):ev==='arrival'?T('marked Present','उपस्थित दर्ज'):T(j.message||'Attendance updated',j.message||'उपस्थिति अपडेट');qs('#svFaceStatus').textContent=`${name} — ${label}`;qs('#svFaceInfo').textContent=`${tm}`;await window.SV357?.refreshAttendance?.();window.SV357?.popup?.(`${name} की ${ev==='departure'?'प्रस्थान':'उपस्थिति'} ${tm} बजे दर्ज की गई।`,'success')}catch(e){qs('#svFaceStatus').textContent=T('Could not save attendance','उपस्थिति सहेजी नहीं जा सकी');window.SV357?.popup?.(e.message||T('Could not save attendance','उपस्थिति सहेजी नहीं जा सकी'),'error')}}
function markFace(){return T('Saving attendance…','उपस्थिति सहेजी जा रही है…')}
function queueSync(item){let q=[];try{q=JSON.parse(localStorage.getItem('sv_offline_queue')||'[]')}catch(e){}q.push({...item,queuedAt:new Date().toISOString()});localStorage.setItem('sv_offline_queue',JSON.stringify(q));if(navigator.onLine)flushQueue()}
