async function saveAdmission13(){let btn=$('#saveAdmissionBtn');try{let name=$('#aName').value.trim(),aad=$('#aAadhaar').value.trim();if(!name||!$('#aGender').value||!$('#aDob').value||!$('#aClass').value||!/^[0-9]{12}$/.test(aad))throw new Error(tr('Fill all required student fields and enter a valid 12-digit Aadhaar number.','सभी आवश्यक विद्यार्थी विवरण भरें और मान्य 12 अंकों का आधार नंबर दर्ज करें।'));if(!$('#aPhoto').files[0]||!$('#aAadhaarFile').files[0])throw new Error(tr('Student photo and Aadhaar card are required.','विद्यार्थी फोटो और आधार कार्ड आवश्यक हैं।'));let guardians=[];for(const card of $$('.sv-guardian-card')){let rel=card.querySelector('.gRelation').value,gn=card.querySelector('.gName').value.trim(),mob=card.querySelector('.gMobile').value.trim();if(!gn&&!mob)continue;if(!gn||!/^[0-9]{10}$/.test(mob))throw new Error(tr('Each added guardian needs a name and valid 10-digit contact number.','जोड़े गए प्रत्येक अभिभावक का नाम और मान्य 10 अंकों का संपर्क नंबर आवश्यक है।'));guardians.push({guardianId:rid('GD'),relation:rel,name:gn,occupation:card.querySelector('.gOccupation').value.trim(),monthlyIncome:card.querySelector('.gIncome').value||'',mobile:mob,aadhaar:card.querySelector('.gAadhaar').value.trim(),aadhaarData:await fileData(card.querySelector('.gAadhaarFile'))})}if(!guardians.length)throw new Error(tr('Add at least one guardian.','कम से कम एक अभिभावक जोड़ें।'));btn.disabled=true;btn.textContent=tr('Saving…','सहेजा जा रहा है…');let student={studentId:$('#aStudentId').value,admissionNo:$('#aAdmission').value,admissionDate:$('#aDate').value,studentName:name,name,gender:$('#aGender').value,dob:$('#aDob').value,studentClass:$('#aClass').value,class:$('#aClass').value,section:$('#aSection').value,rollNo:$('#aRoll').value,mobile:$('#aMobile').value.trim(),email:$('#aEmail').value.trim(),aadhaar:aad,caste:$('#aCaste')?.value?.trim()||'',bloodGroup:$('#aBlood').value,category:$('#aCategory').value,religion:$('#aReligion')?.value||'Hindu',address:$('#aAddress').value.trim(),status:$('#aStatus').value,photoData:await fileData($('#aPhoto')),aadhaarCardData:await fileData($('#aAadhaarFile')),guardianId:guardians[0].guardianId,guardianIds:guardians.map(g=>g.guardianId).join(','),guardianName:guardians[0].name,guardianMobile:guardians[0].mobile,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};guardians.forEach(g=>{g.studentIds=student.studentId;g.studentId=student.studentId;g.studentName=name;g.status='active'});if(navigator.onLine){let j=await api13('saveAdmission',{record:student,guardians});student={...student,...(j.data?.student||{})};guardians=j.data?.guardians||guardians}else{let q=JSON.parse(localStorage.getItem('sv_offline_queue')||'[]');q.push({type:'admission',record:student,guardians});localStorage.setItem('sv_offline_queue',JSON.stringify(q))}['photoData','aadhaarCardData'].forEach(k=>delete student[k]);let sr=get('STUDENTS','svms_students').filter(x=>x.studentId!==student.studentId);sr.push(student);put('STUDENTS','svms_students',sr);let gr=get('GUARDIANS','svms_guardians');guardians.forEach(g=>{gr=gr.filter(x=>x.guardianId!==g.guardianId);let z={...g};delete z.aadhaarData;gr.push(z)});put('GUARDIANS','svms_guardians',gr);close13();toast13(tr('Admission saved successfully.','प्रवेश सफलतापूर्वक सहेजा गया।'));studentsPage()}catch(e){toast13(e.message||tr('Unable to save admission.','प्रवेश सहेजा नहीं जा सका।'),'error')}finally{if(btn){btn.disabled=false;btn.textContent='💾 '+tr('Save Admission','प्रवेश सहेजें')}}}
function listCards(rows,type){return rows.map((r,i)=>{let name=r.studentName||r.teacherName||r.name||r.studentId||r.teacherId,id=r.studentId||r.teacherId||r.admissionNo||'';return `<button class="sv-record-row" onclick="SV13.record('${type}',${i})"><span class="sv-record-avatar">${esc13((name||'?')[0])}</span><span><b>${esc13(name)}</b><small>${esc13(id)}${r.class||r.studentClass?' • '+esc13(r.class||r.studentClass):''}</small></span><span>›</span></button>`}).join('')||`<div class="sv-empty">${tr('No records found.','कोई अभिलेख नहीं मिला।')}</div>`}
function studentsPage(){let rows=get('STUDENTS','svms_students');$('#mainContent').innerHTML=`<div class="sv-mobile-page"><div class="sv-module-actions"><button onclick="SV13.admission()">＋ ${tr('New Admission','नया प्रवेश')}</button><button onclick="SV13.guardians()">👪 ${tr('Guardians','अभिभावक')}</button><button onclick="SV13.ptm()">🤝 PTM</button><button onclick="SV13.export('students')">⬇ XLSX</button></div><div class="sv-register-title"><b>${tr('Student Register','विद्यार्थी पंजी')}</b><span>${rows.length}</span></div><div class="sv-record-list">${listCards(rows,'students')}</div></div>`}
function teachersPage(){let rows=get('TEACHERS','svms_teachers');$('#mainContent').innerHTML=`<div class="sv-mobile-page"><div class="sv-module-actions"><button onclick="SV12.teacherForm()">＋ ${tr('New Teacher','नया शिक्षक')}</button><button onclick="SV13.export('teachers')">⬇ XLSX</button></div><div class="sv-register-title"><b>${tr('Teacher Register','शिक्षक पंजी')}</b><span>${rows.length}</span></div><div class="sv-record-list">${listCards(rows,'teachers')}</div></div>`}
function record13(type,i){let r=(type==='students'?get('STUDENTS','svms_students'):get('TEACHERS','svms_teachers'))[i];if(!r)return;let fields=Object.entries(r).filter(([k,v])=>v!==''&&v!=null&&!/data$|signature|descriptor/i.test(k));modal13(r.studentName||r.teacherName||r.name||tr('Full Details','पूर्ण विवरण'),`<div class="sv-full-detail">${r.photoUrl?`<img class="sv-profile-photo" src="${esc13(r.photoUrl)}">`:''}${fields.map(([k,v])=>`<div><span>${esc13(k.replace(/([A-Z])/g,' $1'))}</span><b>${esc13(/date/i.test(k)?date13(v):v)}</b></div>`).join('')}${r.aadhaarCardUrl?`<div class="sv-doc"><span>${tr('Student Aadhaar Card','विद्यार्थी आधार कार्ड')}</span><a href="${esc13(r.aadhaarCardUrl)}" target="_blank">${tr('Open Document','दस्तावेज़ खोलें')}</a></div>`:''}</div>`)}
function guardiansPage(){let rows=get('GUARDIANS','svms_guardians');$('#mainContent').innerHTML=`<div class="sv-mobile-page"><div class="sv-module-actions"><button onclick="SV13.export('guardians')">⬇ XLSX</button><button onclick="SV13.ptm()">🤝 PTM</button></div><div class="sv-register-title"><b>${tr('Guardian Register','अभिभावक पंजी')}</b><span>${rows.length}</span></div><div class="sv-record-list">${rows.map((g,i)=>`<button class="sv-record-row" onclick="SV13.guardianDetail(${i})"><span class="sv-record-avatar">👪</span><span><b>${esc13(g.name||g.guardianName)}</b><small>${esc13(g.relation||'')} • ${esc13(g.mobile||'')}</small></span><span>›</span></button>`).join('')}</div></div>`}
