function ptmPage(){let rows=get('PTM','svms_ptm');$('#mainContent').innerHTML=`<div class="sv-mobile-page"><div class="sv-module-actions"><button onclick="SV13.ptmForm()">＋ ${tr('New PTM Record','नया पीटीएम अभिलेख')}</button><button onclick="SV13.export('ptm')">⬇ XLSX</button></div><div class="sv-register-title"><b>PTM ${tr('Register','पंजी')}</b><span>${rows.length}</span></div><div class="sv-record-list">${rows.slice().reverse().map((r,i)=>`<button class="sv-record-row" onclick="SV13.ptmDetail(${rows.length-1-i})"><span class="sv-record-avatar">🤝</span><span><b>${esc13(r.studentName||r.studentId)}</b><small>${date13(r.date)} • ${esc13(r.status||'')}</small></span><span>›</span></button>`).join('')}</div></div>`}
function ptmForm(){let ss=get('STUDENTS','svms_students');modal13(tr('New PTM Record','नया पीटीएम अभिलेख'),`<form class="sv13-form" onsubmit="event.preventDefault();SV13.savePTM()"><div class="sv-form-grid"><label>${tr('Student','विद्यार्थी')} *<select id="pStudent" required><option value="">${tr('Select Student','विद्यार्थी चुनें')}</option>${ss.map(s=>`<option value="${esc13(s.studentId)}">${esc13(s.studentName||s.name)} (${esc13(s.studentId)})</option>`).join('')}</select></label><label>${tr('Date','तिथि')} *<input id="pDate" type="date" value="${today()}" required></label><label>${tr('Guardian Attended','उपस्थित अभिभावक')}<input id="pGuardian"></label><label>${tr('Teacher','शिक्षक')}<input id="pTeacher"></label><label>${tr('Status','स्थिति')}<select id="pStatus"><option>Attended</option><option>Absent</option><option>Rescheduled</option></select></label><label class="full">${tr('Discussion / Progress','चर्चा / प्रगति')}<textarea id="pDiscussion"></textarea></label><label class="full">${tr('Action / Follow-up','कार्यवाही / अनुवर्ती')}<textarea id="pAction"></textarea></label></div><button class="sv-primary" type="submit">💾 ${tr('Save PTM','पीटीएम सहेजें')}</button></form>`)}
async function savePTM(){let sid=$('#pStudent').value,s=get('STUDENTS','svms_students').find(x=>x.studentId===sid);if(!sid)return toast13(tr('Select student.','विद्यार्थी चुनें।'),'error');let r={ptmId:rid('PTM'),studentId:sid,studentName:s?.studentName||s?.name||'',date:$('#pDate').value,guardianName:$('#pGuardian').value.trim(),teacherName:$('#pTeacher').value.trim(),status:$('#pStatus').value,discussion:$('#pDiscussion').value.trim(),followUp:$('#pAction').value.trim(),createdAt:new Date().toISOString()};let rows=get('PTM','svms_ptm');rows.push(r);put('PTM','svms_ptm',rows);if(navigator.onLine)await api13('syncCollection',{module:'ptm',rows:[r]});close13();toast13(tr('PTM record saved successfully.','पीटीएम अभिलेख सफलतापूर्वक सहेजा गया।'));ptmPage()}
